<div class="content-wrapper"><section class="content-header"><h1>Surat Permohonan Pengawasan Bunker</h1></section><section class="content"><?php if($error): ?><div class="alert alert-danger"><?= html_escape($error) ?></div><?php endif; ?><div class="box box-primary"><div class="box-body"><form method="post"><?php $this->load->view('pipeline/billing_token'); ?><div class="row"><div class="col-sm-6 form-group"><label>Area</label><select id="bunker-area" name="SpbbID" class="form-control" required><?php foreach($branches as $b): ?><option value="<?= (int)$b['SpbbID'] ?>"><?= html_escape($b['SpbbName']) ?></option><?php endforeach; ?></select></div><div class="col-sm-6 form-group"><label>Kapal / Perusahaan</label><select id="bunker-vessel" name="VesselID" class="form-control" required><option value="">Pilih dari Basic Data</option><?php foreach($vessels as $v): ?><option data-area="<?= (int)$v['SpbbID'] ?>" value="<?= (int)$v['VesselID'] ?>"><?= html_escape($v['VesselName'].' / '.$v['CompanyName']) ?></option><?php endforeach; ?></select></div>
<?php foreach(array('RequestNo'=>'Nomor Surat','RequestDate'=>'Tanggal Surat','Place'=>'Tempat Surat','IssuerName'=>'Nama Perusahaan Penerbit','Recipient'=>'Kepada Yth. KSOP','RecipientPlace'=>'Kota Tujuan Surat','RemainingFuel'=>'Sisa BBM Saat Ini','PlannedLiters'=>'Rencana Bunker (liter)','Supplier'=>'Suplayer','OriginPort'=>'Datang Dari','ArrivalPort'=>'Kapal Tiba','FillingDate'=>'Rencana Tanggal Pengisian','Position'=>'Posisi Kapal','Captain'=>'Nakhoda','SignatoryTitle'=>'Jabatan Penandatangan','Signatory'=>'Nama Penandatangan') as $k=>$label): $date=in_array($k,array('RequestDate','FillingDate')); ?><div class="col-sm-6 form-group"><label><?= $label ?></label><input class="form-control" name="<?= $k ?>" type="<?= $date?'date':($k==='PlannedLiters'?'number':'text') ?>" maxlength="<?= $k==='Recipient'?500:($k==='RequestNo'?100:200) ?>" <?= $k==='PlannedLiters'?'min="0.001" step="0.001"':'' ?> value="<?= html_escape(set_value($k,$date?date('Y-m-d'):'')) ?>" required></div><?php endforeach; ?></div><button class="btn btn-primary">Simpan &amp; Preview Surat</button></form></div></div><div class="box"><div class="box-body table-responsive"><table class="table"><tr><th>Nomor Surat</th><th>Tanggal</th><th>Area</th><th>Output</th></tr><?php foreach($requests as $r): ?><tr><td><?= html_escape($r['RequestNo']) ?></td><td><?= html_escape($r['RequestDate']) ?></td><td><?= (int)$r['SpbbID'] ?></td><td><a href="<?= site_url('Pipeline_setup/print_bunker/'.$r['BunkerID']) ?>" target="_blank">View / Cetak</a> &middot; <a href="<?= site_url('Pipeline_setup/print_bunker/'.$r['BunkerID']).'?pdf=1' ?>">PDF</a></td></tr><?php endforeach; ?><?php if(!$requests): ?><tr><td colspan="4">Belum ada surat permohonan.</td></tr><?php endif; ?></table></div></div></section></div><script>(function(){var a=document.getElementById('bunker-area'),v=document.getElementById('bunker-vessel');function filter(){Array.prototype.forEach.call(v.options,function(o){if(!o.value)return;o.hidden=o.disabled=o.dataset.area!==a.value;if(o.disabled&&o.selected)v.value='';});}a.addEventListener('change',filter);filter();})();</script>